sys_ux_client_script.script:
function handler({api, event, helpers, imports}) {
    // 1. Read the passwords from client state
    const newPassword = api.state.newPassword;
    const confirmPassword = api.state.confirmPassword;

    // 2. Validate empty and matching fields
    if (!newPassword || !confirmPassword) {
        helpers.snMessaging.addErrorMessage("Please fill in both fields.");
        return;
    }
    if (newPassword !== confirmPassword) {
        helpers.snMessaging.addErrorMessage("Passwords do not match.");
        return;
    }

    // 3. Target endpoint & security token
    const endpoint = '/api/x_travel_buddy_app/password_management/update';
    const userToken = window.g_ck || (api.context.session && api.context.session.user ? api.context.session.user.csrfToken : '');

    fetch(endpoint, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
            'X-UserToken': userToken
        },
        body: JSON.stringify({
            password: newPassword
        })
    })
    .then(async res => {
        const data = await res.json();
        if (!res.ok) {
            // Catches HTTP 400, 403, 500 responses
            const errorMsg = data.error ? data.error.message : (data.result ? data.result.message : "Server error");
            throw new Error(errorMsg);
        }
        return data;
    })
    .then(data => {
        if (data.result && data.result.success) {
            helpers.snMessaging.addInfoMessage("Password updated successfully!");
            api.setState('newPassword', '');
            api.setState('confirmPassword', '');
        } else {
            helpers.snMessaging.addErrorMessage("Failed: " + (data.result ? data.result.message : "Unable to update password."));
        }
    })
    .catch(err => {
        helpers.snMessaging.addErrorMessage("Error: " + err.message);
    });
}
